entries[41443] = { ["name"] = "Kessel des erheblichen Arkanschutzes", ["text"] = "5 Meter Reichweite\nWirken in 3 sek.\nStellt einen Kessel her, der von anderen Schlachtzugsmitgliedern benutzt werden kann, um einen erheblichen Arkanschutztrank herbeizuzaubern. Der Kessel enthält 25 Anwendungen und bleibt 5 Min. lang bestehen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[41444] = { ["name"] = "Teufelsflammen", ["text"] = "150 Mana Nahkampfreichweite\nWirken in 2 sek.\nFügt Gegnern in einem kegelförmigen Bereich vor dem Zaubernden 597 Feuerschaden zu, danach 3 Sek. lang weiteren Feuerschaden." }
