entries[41458] = { ["name"] = "Kessel des erheblichen Arkanschutzes", ["text"] = "Wirken in 2.5 sek.\nReagenzien:\nUrmana (2), Manadistel (7), Teufelseisengehäuse\nBeruf:\nAlchemie der Scherbenwelt\nEntdeckung:\nErheblicher Arkanschutztrank\n\nBenutzen: Stellt einen Kessel her, der von anderen Schlachtzugsmitgliedern benutzt werden kann, um einen erheblichen Arkanschutztrank herbeizuzaubern. Der Kessel enthält 25 Anwendungen und bleibt 5 Min. lang bestehen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\n25" }
entries[41459] = { ["name"] = "Siegel des Blutes", ["text"] = "90 Mana\nSofort 15 sek. Abklingzeit\nAlle Nahkampfangriffe fügen zusätzlichen Heiligschaden in Höhe des normalen Waffenschadens zu.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind und verursacht regelmäßig Heiligschaden." }
