entries[41467] = { ["name"] = "Richturteil", ["text"] = "1% von Grundmana 10 Meter Reichweite\nWirken in 2 sek.\nEntfesselt die Energie eines Siegelzaubers auf einen Gegner. Bei dem jeweiligen Siegel kann der Effekt des Richturteils nachgelesen werden." }
