entries[41469] = { ["name"] = "Siegel des Befehls", ["text"] = "265 Mana\nSofort 15 sek. Abklingzeit\nVerleiht dem Zaubernden die Chance, zusätzlichen Heiligschaden in Höhe von 1000% des normalen Waffenschadens zu verursachen. Hält 30 Sek. an.\n\nDas Richturteil dieses Befehls verursacht (42.9% der Zaubermacht) Heiligschaden.\n(1s Abklingzeit)" }
