entries[41604] = { ["name"] = "Oberste Macht von Shattrath", ["text"] = "Sofort 1 sek. Abklingzeit\nErhöht die Zaubermacht 1 Stunde lang um 22 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an." }
