entries[41607] = { ["name"] = "Stärkung von Shattrath", ["text"] = "Sofort\nErhöht die maximale Gesundheit des Spielers 1 Stunde lang um 29 und das Ausweichen um 1 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an." }
entries[41608] = { ["name"] = "Unerbittlicher Angriff von Shattrath", ["text"] = "Sofort\nErhöht die Angriffskraft 1 Stunde lang um 19 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau." }
entries[41609] = { ["name"] = "Stärkung von Shattrath", ["text"] = "Sofort\nErhöht 1 Stunde lang die maximale Gesundheit um 500 und das Ausweichen um 10. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau." }
entries[41610] = { ["name"] = "Mächtige Wiederherstellung von Shattrath", ["text"] = "Sofort\nErhöht die Vielseitigkeit 1 Stunde lang um 20 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und auf dem Sonnenbrunnenplateau." }
entries[41611] = { ["name"] = "Oberste Macht von Shattrath", ["text"] = "Sofort\nErhöht die Schadenswirkung von Zaubern und magischen Effekten 1 Stunde lang um bis zu 70. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau." }
